        var d = v + rhs.v
        if (d >= MOD) d -= MOD
        return ModInt(d)
    }

    operator fun minus(rhs: ModInt): ModInt {
        var d = v + MOD - rhs.v
        if (d >= MOD) d -= MOD
        return ModInt(d)
    }

    operator fun times(rhs: ModInt): ModInt {
        return ModInt(((v.toLong() * rhs.v.toLong()) % MOD.toLong()).toInt())
    }

    operator fun unaryMinus(): ModInt {
        return if (v == 0) ModInt(0) else ModInt(MOD - v)
    }

    fun pow(n0: Int): ModInt {
        var n = n0
        var t = one()
        var s = this
        while (n > 0) {
            if ((n and 1) == 1) {
                t *= s
            }
            s *= s
            n = n shr 1
        }
        return t
    }

    fun inv(): ModInt {
        return pow(MOD - 2)
    }

    companion object {
        fun new(n: Int): ModInt {
            return ModInt(n % MOD)
        }

        fun zero(): ModInt {
            return ModInt(0)
        }

        fun one(): ModInt {
            return ModInt(1)
        }

        fun comb(n: Int, k0: Int): ModInt {
